// Generated from src/registry/sources/control-ui/recipes/emoji-picker.css by scripts/gen-knob-contracts.ts — run `bun run sync:knobs`.
export const emojiPickerKnobs = [
  "--cui-emoji-picker-cell-size",
  "--cui-emoji-picker-cell-radius",
  "--cui-emoji-picker-active-background",
  "--cui-emoji-picker-header-background",
  "--cui-emoji-picker-header-foreground",
] as const;
export type EmojiPickerKnobStyle = Partial<Record<(typeof emojiPickerKnobs)[number], string>>;

@layer components {
  :where([data-control-family="emoji-picker"][data-slot="root"]) {
    --cui-emoji-picker-cell-size: calc(var(--spacing) * 8);
    --cui-emoji-picker-cell-radius: var(--radius-control);
    --cui-emoji-picker-active-background: var(--accent);
    --cui-emoji-picker-header-background: var(--popover);
    --cui-emoji-picker-header-foreground: var(--muted-foreground);
    color: var(--foreground);
    font-family: var(--font-sans);
  }

  :where([data-control-family="emoji-picker"][data-slot="search"]) {
    position: relative;
    margin: calc(var(--spacing) * 2);
    margin-block-end: calc(var(--spacing) * 1);
  }

  :where([data-control-family="emoji-picker"][data-slot="search-icon"]) {
    position: absolute;
    inset-inline-start: calc(var(--spacing) * 2.5);
    inline-size: calc(var(--spacing) * 4);
    block-size: calc(var(--spacing) * 4);
    color: var(--muted-foreground);
    pointer-events: none;
  }

  :where([data-control-family="emoji-picker"][data-slot="search-input"]) {
    block-size: var(--control-h-sm);
    padding-inline: calc(var(--spacing) * 8) calc(var(--spacing) * 2.5);
    border: var(--control-rim-width) solid var(--control-rim);
    border-radius: var(--radius-control);
    background: var(--control-fill);
    box-shadow: var(--shadow-inset);
    color: var(--foreground);
    font-size: var(--text-label);
    --focus-ring-offset: calc(var(--focus-ring-width) * -1);
  }

  :where([data-control-family="emoji-picker"][data-slot="search-input"])::placeholder {
    color: var(--muted-foreground);
  }

  :where([data-control-family="emoji-picker"][data-slot="content"]) {
    overflow-y: auto;
    overscroll-behavior: contain;
    scrollbar-width: thin;
  }

  :where([data-control-family="emoji-picker"][data-slot="loading"]),
  :where([data-control-family="emoji-picker"][data-slot="empty"]) {
    color: var(--muted-foreground);
    font-size: var(--text-label);
  }

  :where([data-control-family="emoji-picker"][data-slot="list"]) {
    padding-block-end: calc(var(--spacing) * 1);
  }

  :where([data-control-family="emoji-picker"][data-slot="category-header"]) {
    padding: calc(var(--spacing) * 1.5) calc(var(--spacing) * 2.5) calc(var(--spacing) * 1);
    background: var(--cui-emoji-picker-header-background);
    color: var(--cui-emoji-picker-header-foreground);
    font-size: var(--text-caption);
    font-weight: var(--font-weight-medium);
  }

  :where([data-control-family="emoji-picker"][data-slot="row"]) {
    padding-inline: calc(var(--spacing) * 1.5);
  }

  :where([data-control-family="emoji-picker"][data-slot="emoji"]) {
    inline-size: var(--cui-emoji-picker-cell-size);
    block-size: var(--cui-emoji-picker-cell-size);
    border-radius: var(--cui-emoji-picker-cell-radius);
    background: transparent;
    font-size: 1.25rem;
    line-height: 1;
    cursor: default;
  }

  :where([data-control-family="emoji-picker"][data-slot="emoji"][data-active]) {
    background: var(--cui-emoji-picker-active-background);
  }

  :where([data-control-family="emoji-picker"][data-slot="footer"]) {
    gap: calc(var(--spacing) * 2);
    min-block-size: calc(var(--spacing) * 11);
    padding-inline: calc(var(--spacing) * 2.5);
    border-block-start: 1px solid var(--border);
    color: var(--muted-foreground);
    font-size: var(--text-label);
  }

  :where([data-control-family="emoji-picker"][data-slot="footer-emoji"]) {
    font-size: 1.25rem;
    line-height: 1;
  }

  :where([data-control-family="emoji-picker"][data-slot="footer-label"]) {
    color: var(--foreground);
  }
}

@property --cui-emoji-picker-cell-size {
  syntax: "<length>";
  inherits: true;
  initial-value: 0px;
}

@property --cui-emoji-picker-cell-radius {
  syntax: "<length-percentage>";
  inherits: true;
  initial-value: 0px;
}

@property --cui-emoji-picker-active-background {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --cui-emoji-picker-header-background {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --cui-emoji-picker-header-foreground {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

"use client";

import {
  type EmojiPickerListCategoryHeaderProps,
  type EmojiPickerListEmojiProps,
  type EmojiPickerListRowProps,
  EmojiPicker as EmojiPickerPrimitive,
} from "frimousse";
import { SearchIcon } from "lucide-react";
import type { ComponentProps, CSSProperties } from "react";
import type { EmojiPickerKnobStyle } from "@/components/control-ui/knob-contracts/emoji-picker-knobs";
import { cn } from "@/components/control-ui/lib/cn";
import { Spinner } from "@/components/control-ui/ui/spinner";

type EmojiPickerStyle = { style?: CSSProperties & EmojiPickerKnobStyle };

export type EmojiPickerProps = Omit<ComponentProps<typeof EmojiPickerPrimitive.Root>, "style"> & EmojiPickerStyle;

export function EmojiPicker({ className, columns = 9, ...props }: EmojiPickerProps) {
  return (
    <EmojiPickerPrimitive.Root
      data-control-ui="emoji-picker"
      data-control-family="emoji-picker"
      data-slot="root"
      columns={columns}
      className={cn("isolate flex h-72 w-fit flex-col", className)}
      {...props}
    />
  );
}

export type EmojiPickerSearchProps = Omit<ComponentProps<typeof EmojiPickerPrimitive.Search>, "style"> & EmojiPickerStyle;

export function EmojiPickerSearch({
  className,
  placeholder = "Search emoji…",
  "aria-label": ariaLabel = "Search emoji",
  ...props
}: EmojiPickerSearchProps) {
  return (
    <div data-control-ui="emoji-picker" data-control-family="emoji-picker" data-slot="search" className="flex items-center">
      <SearchIcon aria-hidden="true" data-control-ui="emoji-picker" data-control-family="emoji-picker" data-slot="search-icon" />
      <EmojiPickerPrimitive.Search
        data-control-ui="emoji-picker"
        data-control-family="emoji-picker"
        data-slot="search-input"
        placeholder={placeholder}
        aria-label={ariaLabel}
        className={cn("min-w-0 flex-1", className)}
        {...props}
      />
    </div>
  );
}

function EmojiPickerRow({ children, className, ...props }: EmojiPickerListRowProps) {
  return (
    <div
      data-control-ui="emoji-picker"
      data-control-family="emoji-picker"
      data-slot="row"
      className={cn("scroll-my-1", className)}
      {...props}
    >
      {children}
    </div>
  );
}

function EmojiPickerEmoji({ emoji, className, ...props }: EmojiPickerListEmojiProps) {
  return (
    <button
      data-control-ui="emoji-picker"
      data-control-family="emoji-picker"
      data-slot="emoji"
      data-active={emoji.isActive ? "" : undefined}
      className={cn("flex items-center justify-center", className)}
      {...props}
    >
      {emoji.emoji}
    </button>
  );
}

function EmojiPickerCategoryHeader({ category, className, ...props }: EmojiPickerListCategoryHeaderProps) {
  return (
    <div data-control-ui="emoji-picker" data-control-family="emoji-picker" data-slot="category-header" className={className} {...props}>
      {category.label}
    </div>
  );
}

export type EmojiPickerContentProps = Omit<ComponentProps<typeof EmojiPickerPrimitive.Viewport>, "style"> & EmojiPickerStyle;

export function EmojiPickerContent({ className, ...props }: EmojiPickerContentProps) {
  return (
    <EmojiPickerPrimitive.Viewport
      data-control-ui="emoji-picker"
      data-control-family="emoji-picker"
      data-slot="content"
      className={cn("relative flex-1 outline-none", className)}
      {...props}
    >
      <EmojiPickerPrimitive.Loading
        data-control-ui="emoji-picker"
        data-control-family="emoji-picker"
        data-slot="loading"
        className="absolute inset-0 flex items-center justify-center"
      >
        <Spinner label="Loading emoji" />
      </EmojiPickerPrimitive.Loading>
      <EmojiPickerPrimitive.Empty
        data-control-ui="emoji-picker"
        data-control-family="emoji-picker"
        data-slot="empty"
        className="absolute inset-0 flex items-center justify-center"
      >
        No emoji found.
      </EmojiPickerPrimitive.Empty>
      <EmojiPickerPrimitive.List
        data-control-ui="emoji-picker"
        data-control-family="emoji-picker"
        data-slot="list"
        className="select-none"
        components={{ Row: EmojiPickerRow, Emoji: EmojiPickerEmoji, CategoryHeader: EmojiPickerCategoryHeader }}
      />
    </EmojiPickerPrimitive.Viewport>
  );
}

export type EmojiPickerFooterProps = Omit<ComponentProps<"div">, "style" | "children"> & EmojiPickerStyle & { placeholder?: string };

export function EmojiPickerFooter({ className, placeholder = "Pick an emoji…", ...props }: EmojiPickerFooterProps) {
  return (
    <div
      data-control-ui="emoji-picker"
      data-control-family="emoji-picker"
      data-slot="footer"
      className={cn("flex min-w-0 items-center", className)}
      {...props}
    >
      <EmojiPickerPrimitive.ActiveEmoji>
        {({ emoji }) =>
          emoji ? (
            <>
              <span data-control-ui="emoji-picker" data-control-family="emoji-picker" data-slot="footer-emoji" className="flex-none">
                {emoji.emoji}
              </span>
              <span data-control-ui="emoji-picker" data-control-family="emoji-picker" data-slot="footer-label" className="truncate">
                {emoji.label}
              </span>
            </>
          ) : (
            <span data-control-ui="emoji-picker" data-control-family="emoji-picker" data-slot="footer-placeholder" className="truncate">
              {placeholder}
            </span>
          )
        }
      </EmojiPickerPrimitive.ActiveEmoji>
    </div>
  );
}
